'use client';
import { useEffect, useMemo, useRef, useState } from 'react';
import { advance, agentCount, agentStatus, computeCost, capitalOffers, demandStake, arr, batch, command, count, createCompany, forecast, luckDistribution, metrics, queueCap, signal, skillCost, tier, units, unlocked } from '../../game/founder/engine';
import { AXES, FUNCTIONS, NAMES, P, SEGMENTS, skillRank, UPGRADES, type Axis, type Work } from '../../game/founder/profile';
import { loanPayment, loanPayoff, loanSchedule, QUARTER_TICKS, type CapitalOffer } from '../../game/founder/finance';
import type { Command, Company } from '../../game/founder/model';
import { BACKUP_SAVE_KEY, encodeSave, HISTORY_KEY, SAVE_KEY } from '../../game/founder/save';
import {ProductToy,ExpansionToy,RetentionToy,OperationsToy,PricingToy,QuarterDraft} from './ToyRooms';
import { measureOperationsTickets } from '../../game/founder/toys';
import { BUILD_FAMILIES, REWARD_EFFECTS, consumableUse, rewardById } from '../../game/founder/rewards';
import { decodeFounderHistory, syncFounderHistory } from '../../game/founder/history';
import { environment, decodePresentation, PRESENTATION_KEY, type FeedbackIntensity } from '../../game/founder/presentation';
import { Milestone, RunSummary } from './RunPresentation';
import { persistCheckpoint, recoverCheckpoint, exportCheckpoints, PENDING_SAVE_KEY } from '../../game/founder/storage';
import { openCheckpointStore, type CheckpointStore } from '../../game/founder/checkpoint-db';
import './founder.css';
import './toys.css';

type Send=(c:Command)=>void;
const money=(c:number)=>{const v=c/100;return v>=1e9?`$${(v/1e9).toFixed(2)}B`:v>=1e6?`$${(v/1e6).toFixed(2)}M`:v>=1e4?`$${(v/1e3).toFixed(1)}k`:`$${v.toLocaleString('en-US',{maximumFractionDigits:0})}`;};
const cash=(cents:number)=>(cents/100).toLocaleString('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2});
const time=(ticks:number)=>{const t=Math.max(0,Math.ceil(ticks/10));return `${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`;};
const TITLES:Record<Work,[string,string]>={demand:['Find the signal.','Swipe right to pursue a real need. Left to keep your cash.'],product:['Less roadmap. More recipe.','Read the brief, combine the ingredients, test the build. Then ship something useful.'],monetisation:['Stick the landing.','Choose your price. Catch the sweet spot. Try not to negotiate with yourself.'],retention:['Put out the customer fires.','Clear real problems before the clock turns customers into churn.'],expansion:['Small features. Bigger deals.','Merge matching pieces into higher tiers. Serve the customer’s next big ask.'],operations:['Read the fine print.','Pay, scratch, inspect. Finish worthwhile patches or walk away from the ticket.']};

export default function FounderGame(){
  const [intensity,setIntensity]=useState<FeedbackIntensity>('full');
  const requestSave=useRef<(()=>Promise<void>)|null>(null);const checkpointStore=useRef<CheckpointStore|null>(null);const replacing=useRef(false);const saveBlocked=useRef(false);const [recoveryBlocked,setRecoveryBlocked]=useState(false);const confirmDialog=useRef<HTMLDialogElement>(null);

  const [gesture,setGesture]=useState(false);
  useEffect(()=>{const down=()=>setGesture(true),up=()=>setGesture(false);window.addEventListener('pointerdown',down);window.addEventListener('pointerup',up);window.addEventListener('pointercancel',up);window.addEventListener('blur',up);return()=>{window.removeEventListener('pointerdown',down);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',up);window.removeEventListener('blur',up);};},[]);
  const [s,setS]=useState<Company>(()=>createCompany(84022));const current=useRef(s);const [boot,setBoot]=useState(false);const [saveStatus,setSaveStatus]=useState('Saved on this device');const [notice,setNotice]=useState('');const [sound,setSound]=useState(false);const audio=useRef<AudioContext|null>(null);const [newRun,setNewRun]=useState(false);const [settings,setSettings]=useState(false);
  useEffect(()=>{if(newRun)confirmDialog.current?.showModal();},[newRun]);
  const commit=(next:Company)=>{current.current=next;setS(next);};
  const send:Send=c=>{
    if(replacing.current)return;
    const priorPhase=current.current.phase,next=command(current.current,c);commit(next);if(next.phase!==priorPhase||['pause','draft','draft-skip','buy','consume','borrow','raise','repay-debt'].includes(c.type))void requestSave.current?.();
    if(sound&&next.actionResults.at(-1)?.type==='ACTION_COMMITTED'&&c.type!=='focus'&&c.type!=='channel'){try{audio.current??=new AudioContext();void audio.current.resume();const o=audio.current.createOscillator(),g=audio.current.createGain();o.type='sine';o.frequency.setValueAtTime(c.type==='buy'?520:180,audio.current.currentTime);o.frequency.exponentialRampToValueAtTime(90,audio.current.currentTime+.07);g.gain.setValueAtTime(.035,audio.current.currentTime);g.gain.exponentialRampToValueAtTime(.0001,audio.current.currentTime+.1);o.connect(g);g.connect(audio.current.destination);o.start();o.stop(audio.current.currentTime+.12);}catch{setSound(false);}}
  };
  useEffect(()=>{
    let disposed=false;
    void openCheckpointStore().then(store=>{ if(disposed){store.close();return;}checkpointStore.current=store;
    try{const prefs=decodePresentation(localStorage.getItem(PRESENTATION_KEY));setSound(prefs.sound);setIntensity(prefs.intensity);const restored=recoverCheckpoint(store);if(restored){saveBlocked.current=restored.invalid.length>0;setRecoveryBlocked(saveBlocked.current); let loaded=restored.company;let historyNotice='';try{syncFounderHistory(localStorage,loaded);}catch{historyNotice='Company restored. Founder history could not be saved; preserve this run and check device storage.';}if(loaded.phase==='active'||loaded.phase==='continuation')loaded=command(loaded,{type:'pause'});current.current=loaded;setS(loaded);setNotice(historyNotice||(restored.source!==SAVE_KEY?'Primary checkpoint was invalid. Restored the last-known-good copy.':'Checkpoint restored. Resume when you are ready.'));}else{const h=decodeFounderHistory(localStorage.getItem(HISTORY_KEY));const fresh=createCompany(crypto.getRandomValues(new Uint32Array(1))[0],h.wins.length);current.current=fresh;setS(fresh);}}
    catch{saveBlocked.current=true;setRecoveryBlocked(true);setNotice('The saved checkpoint could not be verified. It has not been overwritten. Start a new company to recover.');setSaveStatus('Unverified checkpoint preserved');}
    setBoot(true);
    }).catch(()=>{if(!disposed){saveBlocked.current=true;setRecoveryBlocked(true);setSaveStatus('Checkpoint storage unavailable');setNotice('Checkpoint storage could not be opened. Close other game tabs and reload. Existing saves remain untouched.');setBoot(true);}});
    return()=>{disposed=true;checkpointStore.current?.close();void audio.current?.close();};
  },[]);
  useEffect(()=>{
    if(!boot)return;let previous=performance.now(),carry=0,lastSave=0;let frame=0;
    let lastSaved:Company|null=null,saving=false,saveAgain=false;
    const save=async()=>{if(saving){saveAgain=true;return;}if(replacing.current||!checkpointStore.current||saveBlocked.current||current.current.phase==='setup'||current.current===lastSaved)return;const snapshot=current.current;saving=true;setSaveStatus('Saving checkpoint…');try{persistCheckpoint(checkpointStore.current,snapshot);await checkpointStore.current.flush();syncFounderHistory(localStorage,snapshot);lastSaved=snapshot;setSaveStatus('Saved on this device');}catch(error){setSaveStatus(error instanceof Error?`${error.message} Export checkpoint in Settings.`:'Storage unavailable · export checkpoint in Settings');}finally{saving=false;if(saveAgain){saveAgain=false;void save();}}};
    requestSave.current=save;
    const loop=(now:number)=>{carry+=Math.min(250,now-previous);previous=now;if(carry>=100){const ticks=Math.floor(carry/100);carry-=ticks*100;if(!document.hidden&&!replacing.current){try{const next=advance(current.current,ticks);if(next!==current.current){current.current=next;setS(next);if(['unicorn','quarter-draft','failure'].includes(next.phase))void save();}}catch{current.current=command(current.current,{type:'pause'});setS(current.current);setNotice('Simulation interrupted. Your company is paused; the last checkpoint is preserved.');}}}if(now-lastSave>5000){lastSave=now;save();}frame=requestAnimationFrame(loop);};
    frame=requestAnimationFrame(loop);
    const hide=()=>{if(document.hidden&&(current.current.phase==='active'||current.current.phase==='continuation')){current.current=command(current.current,{type:'pause'});setS(current.current);}save();previous=performance.now();carry=0;};
    document.addEventListener('visibilitychange',hide);window.addEventListener('pagehide',save);
    return()=>{requestSave.current=null;cancelAnimationFrame(frame);document.removeEventListener('visibilitychange',hide);window.removeEventListener('pagehide',save);};
  },[boot]);
  const reset=async()=>{if(replacing.current)return;replacing.current=true;try{
    const store=checkpointStore.current;if(!store)throw new Error("Checkpoint storage is not ready");
    const history=syncFounderHistory(localStorage,current.current),fresh=createCompany(crypto.getRandomValues(new Uint32Array(1))[0],history.wins.length),raw=encodeSave(fresh);
    store.setItem(PENDING_SAVE_KEY,raw);store.setItem(BACKUP_SAVE_KEY,raw);store.setItem(SAVE_KEY,raw);store.removeItem(PENDING_SAVE_KEY);await store.flush();saveBlocked.current=false;setRecoveryBlocked(false);commit(fresh);setNewRun(false);setNotice('');
  }catch{setNotice('Could not preserve this run and founder history. Free device storage before starting another company.');}finally{replacing.current=false;}};
  useEffect(()=>{if(boot){try{localStorage.setItem(PRESENTATION_KEY,JSON.stringify({sound,intensity}));}catch{/* Cosmetic preferences never block a run. */}}},[boot,sound,intensity]);
  const exportRun=()=>{try{const data=saveBlocked.current?exportCheckpoints(checkpointStore.current??localStorage):JSON.stringify({company:encodeSave(current.current),history:localStorage.getItem(HISTORY_KEY)},null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`solounicorn-${current.current.seed}.json`;a.click();URL.revokeObjectURL(url);return true;}catch{setNotice('Export failed. Keep this tab open and free device storage.');return false;}};
  const acceptRecovery=async()=>{if(replacing.current||!exportRun())return;replacing.current=true;try{const store=checkpointStore.current;if(!store)return;const raw=encodeSave(current.current);store.setItem(PENDING_SAVE_KEY,raw);store.setItem(BACKUP_SAVE_KEY,raw);store.setItem(SAVE_KEY,raw);store.removeItem(PENDING_SAVE_KEY);await store.flush();saveBlocked.current=false;setRecoveryBlocked(false);setNotice('Recovered company saved. Prior stored copies were exported.');}catch{setNotice('Recovery write failed. Keep the exported checkpoint and this tab open.');}finally{replacing.current=false;}};
  if(!boot)return <main className="founder-game f-boot">Opening the garage…</main>;
  const e=environment(s),m=metrics(s),stage=tier(s),latest=s.log.at(-1),report=s.reports.at(-1),threats=s.accounts.filter(a=>a.active&&a.threat),pricing=s.pricingResolution;
  const queue=(f:Work)=>f==='demand'?s.market[s.channel]:f==='product'?count(s.leads):f==='monetisation'?count(s.trials):f==='retention'?threats.length:f==='expansion'?s.accounts.filter(a=>a.active&&a.addons<2&&a.health>=60&&s.tick-a.born>=1200).length:Math.round(s.strain+m.rot*100);
  return <main className={`founder-game f-tier-${stage}`} data-intensity={intensity} data-environment={e.index} data-distress={e.distress} data-room={s.focus} data-phase={s.phase} data-tick={s.tick}>
    {s.phase==='setup'?<div className="f-entry"><div className="f-wordmark">ONE PERSON<br/><b>UNICORN</b><span>AN OPERATING SIMULATION</span></div><div className="f-entry-scene"><div className="f-entry-orbit"/><span className="f-serial">COMPANY NO. {String(s.seed).slice(-6)}</span><div className="f-founder-object"><div/><i/><b>1</b></div><p>YOU ARE THE ENTIRE COMPANY.</p></div><div className="f-entry-copy"><span className="f-eyebrow">GARAGE → $1,000,000,000</span><h1>Build the thing.<br/>Become the machine.</h1><p>Six jobs. One pair of hands. Turn real work into customers, then teach agents to do it. Survive the company you create.</p><dl><div><dt>STARTING CASH</dt><dd>{money(s.cash)}</dd></div><div><dt>GROWTH DEADLINE</dt><dd>Only if you take VC</dd></div><div><dt>YOUR FIRST MOVE</dt><dd>Find a customer need</dd></div></dl>{s.inheritedWins>0&&<p>{s.inheritedWins} successful companies · {money(s.inheritedWins*P.winCashBonus)} inherited starting cash</p>}<button className="f-primary" disabled={recoveryBlocked} onClick={()=>send({type:'start'})}>Open the garage <span>↗</span></button>{notice&&<p role="status">{notice}</p>}{recoveryBlocked&&<div><button onClick={exportRun}>Export stored checkpoints</button><button onClick={()=>setNewRun(true)}>Replace company…</button></div>}<small>A roguelike founder sim · Local save · Candidate balance</small></div></div>:<>
          <header className="f-hud"><div className="f-brand"><b>ONE / PERSON</b><span>{e.name}</span></div><Metric label="VALUATION" value={money(m.valuation)} sub="TARGET $1B" major/><Metric label="ARR" value={money(m.arr)} sub={`${s.accounts.filter(a=>a.active).reduce((n,a)=>n+a.count,0)} paying customers`}/><Metric label="LIQUID CASH" value={money(s.cash)} sub={`${money(s.expenseAccrued)} bill accruing`} warning={s.cash<m.cost}/><div className="f-clock"><span>QUARTER {String(s.quarter).padStart(2,'0')}</span><strong>{time(1800-s.tick%1800)}</strong><div><i style={{width:`${(s.tick%1800)/18}%`}}/></div></div><button className="f-pause" onClick={()=>send(s.phase==='paused'?{type:'continue'}:{type:'pause'})} disabled={!['active','continuation','paused'].includes(s.phase)}>{s.phase==='paused'?'Continue':'Pause'}</button></header>
      {pricing?.actionId===s.actionResults.at(-1)?.actionId&&<PricingFlash pricing={pricing!}/>}
      <div className="f-garage-scene" style={{backgroundPosition:`${(e.tile%3)*50}% ${Math.floor(e.tile/3)*100}%`}}><Milestone s={s}/><div className="f-garage-pegboard" aria-hidden="true"><i/><i/><i/></div><div className="f-garage-lamp" aria-hidden="true"/><div className="f-layout"><aside className="f-navigation"><div className="f-nav-caption">YOUR ATTENTION</div>{FUNCTIONS.map((f,i)=><button key={f} disabled={!unlocked(s,f)} onClick={()=>send({type:'focus',work:f})} className={s.focus===f?'selected':''} aria-current={s.focus===f?'page':undefined}><span className="f-nav-no">0{i+1}</span><span>{NAMES[f]}<small>{agentCount(s,f)?`${agentCount(s,f)} agent${agentCount(s,f)>1?'s':''} · ${agentStatus(s,f).label}`:unlocked(s,f)?'Manual':'Needs customers'}</small></span><b>{queue(f)||'·'}</b></button>)}<div className="f-nav-caption">BUILD THE COMPANY</div><button className={s.focus==='skills'?'selected':''} onClick={()=>send({type:'focus',work:'skills'})}><span className="f-nav-no">↗</span><span>Skill trees<small>Craft · Scale · Automate · Luck</small></span></button><button className={s.focus==='finance'?'selected':''} onClick={()=>send({type:'focus',work:'finance'})}><span className="f-nav-no">$</span><span>Finance<small>{report&&!report.chosen&&report.choices.length>0?'Quarter choice ready':'Cashflow & capital'}</small></span><b>{report&&!report.chosen&&report.choices.length>0?'!':''}</b></button><div className="f-nav-bottom"><span>SEED {s.seed}</span><button onClick={()=>setSound(!sound)}>{sound?'Sound on':'Sound off'}</button><label className="f-feedback-control">Motion<select value={intensity} onChange={event=>setIntensity(event.target.value as FeedbackIntensity)}><option value="full">Full</option><option value="quiet">Reduced</option><option value="off">Off</option></select></label><button onClick={exportRun}>Export checkpoint</button>{recoveryBlocked&&<button onClick={acceptRecovery}>Export originals and save recovered company</button>}<button onClick={()=>setNewRun(true)}>New company</button></div></aside>
      <div className="f-mobile-actions"><button onClick={()=>send({type:'focus',work:'skills'})}>Skill trees ↗</button><button onClick={()=>send({type:'focus',work:'finance'})}>Finance {report&&!report.chosen&&report.choices.length>0?'· NEW CHOICE':'$'}</button><button onClick={()=>setSettings(!settings)}>Settings</button>{settings&&<div><button onClick={()=>setSound(!sound)}>{sound?'Mute sound':'Enable sound'}</button><label className="f-feedback-control">Motion<select value={intensity} onChange={event=>setIntensity(event.target.value as FeedbackIntensity)}><option value="full">Full</option><option value="quiet">Reduced</option><option value="off">Off</option></select></label><button onClick={exportRun}>Export checkpoint</button>{recoveryBlocked&&<button onClick={acceptRecovery}>Export originals and save recovered company</button>}<button onClick={()=>setNewRun(true)}>New company</button></div>}{threats.length>0&&<button className="f-mobile-threat" onClick={()=>send({type:'focus',work:'retention'})}>{threats.length} account threats · {time(Math.min(...threats.map(a=>a.threat))-s.tick)} left →</button>}</div><section className="f-main">
        {s.phase==='quarter-draft'&&<QuarterDraft defer={gesture} s={s} send={send}/>}
        {s.phase==='failure'||s.phase==='unicorn'?<div className="f-terminal"><span className="f-eyebrow">{s.phase==='unicorn'?'THE ONE PERSON UNICORN':'THE RUN IS OVER'}</span><h1>{s.phase==='unicorn'?'One founder.\nOne billion.':'The company\nran out of road.'}</h1><p>{s.phase==='unicorn'?`This win earns +${money(P.winCashBonus)} starting cash on future runs. Keep operating, or bring that experience to a fresh garage.`:`${s.failure} ${s.wonAt!==null?'Your earlier unicorn win stays in founder history.':'Failed runs award no new starting advantage.'}`}</p><p>{s.inventory.relics.length} relics · {s.reports.filter(r=>r.chosen&&r.chosen!=='passed').length} quarter choices · {s.vc?'VC mandate':s.debt?'Debt financed':'Self-funded now'}</p><RunSummary s={s}/><div><Metric label="FINAL VALUATION" value={money(m.valuation)}/><Metric label="TIME OPERATING" value={time(s.tick)}/></div>{s.phase==='unicorn'&&<button className="f-primary" onClick={()=>send({type:'continue'})}>Keep operating ↗</button>}<button className="f-secondary" onClick={reset}>Start another company</button></div>:s.phase==='paused'?<div className="f-paused"><span className="f-eyebrow">FOUNDER AWAY</span><h1>Take a breath.</h1><p>Your build is saved. Queues, consumable timers and bills wait for Continue.</p><button className="f-primary" onClick={()=>send({type:'continue'})}>Continue ↗</button><small>{notice||saveStatus}</small></div>:s.focus==='skills'?<Skills s={s} send={send}/>:s.focus==='finance'?<Finance s={s} send={send}/>:<>
        <div className="f-room-heading"><div><span className="f-eyebrow">0{FUNCTIONS.indexOf(s.focus)+1} / {NAMES[s.focus].toUpperCase()} <i/> {s.ranks[s.focus].automate?'FOUNDER + AGENTS':'HANDS ON'}</span><h1>{TITLES[s.focus][0]}</h1><p>{TITLES[s.focus][1]}</p></div><span className="f-work-stamp">{s.deployed[s.focus]>s.tick?'INSTALLING':'READY'}<b>{batch(s,s.focus)}×</b>OUTPUT / WORK<small>{units(s,s.focus)} lane{units(s,s.focus)===1?'':'s'} · {queueCap(s,s.focus)} finite slots</small></span></div>
        <div className="f-toy" key={s.focus}>{s.focus==='demand'?<Demand s={s} send={send}/>:s.focus==='product'?<ProductToy s={s} send={send}/>:s.focus==='monetisation'?<PricingToy s={s} send={send}/>:s.focus==='retention'?<RetentionToy s={s} send={send}/>:s.focus==='expansion'?<ExpansionToy s={s} send={send}/>:<OperationsToy s={s} send={send}/>}</div>
        <div className="f-underbench"><span>{s.ranks[s.focus].automate?`${s.completed[s.focus]} outputs · ${Math.round(s.rot[s.focus]*100)}% context rot`:'ONE FOUNDER. STILL ONLY TWO HANDS.'}</span><button onClick={()=>send({type:'focus',work:'skills'})}>{s.ranks[s.focus].automate?'Improve this system':'Teach an agent this job'} ↗</button></div>
        </>}
      </section>
      <aside className="f-awareness"><div className="f-awareness-title"><span>THE COMPANY</span><i className={s.phase==='paused'?'paused':''}/></div><CompanyScope s={s} intensity={intensity}/><div className="f-pipeline"><button onClick={()=>send({type:'focus',work:'product'})}><b>{count(s.leads)}</b><span>qualified<br/>opportunities</span></button><i>→</i><button onClick={()=>send({type:'focus',work:'monetisation'})}><b>{count(s.trials)}</b><span>activated<br/>trials</span></button></div><div className="f-health"><span>OPERATING STABILITY</span><b>{Math.round(m.stability*100)}%</b><div><i style={{width:`${m.stability*100}%`}}/></div><p>{m.overload>.3?'Coordination is slowing work. Repair strain or improve Operations.':m.rot>.2?'Your agents are drifting. Operations can refresh their context.':'Room to breathe. Keep the next bill covered.'}</p></div>{(stage>0||m.rot>0||s.strain>0)&&<dl className="f-pressure"><div><dt>Strain backlog</dt><dd>{s.strain.toFixed(1)}</dd></div><div><dt>Worst context rot</dt><dd>{Math.round(m.rot*100)}%</dd></div><div><dt>Agent pace</dt><dd>{Math.round(m.speed*100)}% before context rot</dd></div><div><dt>Coordination</dt><dd>{m.load.toFixed(1)} / {m.capacity.toFixed(1)}</dd></div></dl>}<button className="f-obligation" onClick={()=>send({type:'focus',work:'finance'})}><span>NEXT OPERATING BILL</span><strong>~{money(m.nextBill)}</strong><small>Due in {time(600-s.tick%600)} · cash {money(s.cash)}</small></button>{threats.length>0&&<button className="f-alert" onClick={()=>send({type:'focus',work:'retention'})}>{threats.length} churn threat{threats.length>1?'s':''} · {time(Math.min(...threats.map(a=>a.threat))-s.tick)} left →</button>}<FinanceAlerts s={s} send={send}/>{report&&!report.chosen&&report.choices.length>0&&<button className="f-quarter-notice" onClick={()=>send({type:'focus',work:'finance'})}>Q{report.quarter} closed. Choose what changes. ↗</button>}<BuildContext s={s} send={send}/><ProgressiveHUD s={s}/><small className="f-save-status" role="status">{recoveryBlocked?"Saving paused to preserve incompatible data. Export in Settings.":saveStatus}</small></aside></div></div>
      <footer className={`f-receipt ${latest?.kind??''}`} role="status"><span>{latest?time(latest.tick):'0:00'} / FIELD NOTES</span><p key={latest?.id}>{latest?.text??'The company is running.'}</p><b>01 FOUNDER / {s.accounts.filter(a=>a.active).reduce((n,a)=>n+a.count,0)} CUSTOMERS</b></footer>
    </>}
    {newRun&&<dialog ref={confirmDialog} className="f-confirm" onCancel={()=>setNewRun(false)} aria-label="Start a new company"><h2>Close this company?</h2><p>This replaces the current local run. Your successful founder history stays.</p><button className="f-primary" onClick={reset}>Start a new company</button><button className="f-secondary" onClick={()=>setNewRun(false)}>Keep this run</button></dialog>}
  </main>;
}
function Metric({label,value,sub,major,warning}:{label:string;value:string;sub?:string;major?:boolean;warning?:boolean}){return <div className={`f-metric ${major?'major':''} ${warning?'warning':''}`}><span>{label}</span><strong key={value}>{value}</strong>{sub&&<small>{sub}</small>}</div>;}
function PricingFlash({pricing}:{pricing:NonNullable<Company['pricingResolution']>}){return <div className={`f-pricing-flash ${pricing.outcome}`} role="status"><b>{pricing.outcome==='signed'?`+${money(pricing.arrDelta)} ARR`:'NO ARR'}</b><span>{pricing.customers} customer{pricing.customers===1?'':'s'} · cash follows billing{pricing.luckDelta?` · Luck ${pricing.luckDelta>0?'+':'−'}${Math.abs(pricing.luckDelta)*4}%`:''}</span></div>;}
function Demand({s,send}:{s:Company;send:Send}){
  const [drag,setDrag]=useState(0);const origin=useRef<{x:number;y:number;signal:number;pointer:number;axis:'pending'|'x'|'y'}|null>(null);const candidate=signal(s);const clear=()=>{origin.current=null;setDrag(0);};
  useEffect(()=>{window.addEventListener('blur',clear);window.addEventListener('resize',clear);return()=>{window.removeEventListener('blur',clear);window.removeEventListener('resize',clear);};},[]);
  const title=[['My work lives in twelve different tabs.','I spend Sundays doing work a tool should do.'],['Our team keeps losing the handoff.','Nobody knows which version is the real one.'],['We need an audit trail we can actually trust.','Every exception ends up on one person’s desk.']][s.channel][s.signal%2];
  const stake=demandStake(s),resolution=s.demandResolution;
  const commit=(pursue:boolean,signalId=s.signal)=>send({type:'demand',pursue,signal:signalId});
  return <div className="f-demand"><div className="f-channel-picker" aria-label="Acquisition channel">{SEGMENTS.map((n,i)=><button key={n} aria-pressed={s.channel===i} onClick={()=>{clear();send({type:'channel',channel:i});}}>{['Creators','Teams','Enterprise'][i]} <small>{money(P.acquisitionCents[i])} / try</small></button>)}</div>
    <div className="f-demand-helper"><b>FIRST SIGNAL</b><span>Read fit and stake. Swipe right commits the visible profile. Swipe left costs nothing.</span></div>
    <div className="f-swipe-stage"><span className={`f-swipe-label left ${drag<-40?'lit':''}`}>PASS<br/>KEEP CASH</span><article className={`f-signal ${drag!==0?'dragging':''} ${drag>45?'pursue':drag<-45?'pass':''} quality-${candidate.quality}`} tabIndex={0} aria-label="Customer profile. Swipe right to qualify it, left to pass. Arrow keys also work." onKeyDown={e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();commit(e.key==='ArrowRight');}}} onPointerDown={e=>{if(!e.isPrimary||e.button!==0)return;e.currentTarget.setPointerCapture(e.pointerId);origin.current={x:e.clientX,y:e.clientY,signal:s.signal,pointer:e.pointerId,axis:'pending'};}} onPointerMove={e=>{const p=origin.current;if(!p||p.pointer!==e.pointerId)return;const x=e.clientX-p.x,y=e.clientY-p.y;if(p.axis==='pending'&&Math.hypot(x,y)>8)p.axis=Math.abs(x)>Math.abs(y)?'x':'y';if(p.axis==='x')setDrag(x);}} onPointerUp={e=>{const p=origin.current,dx=p?e.clientX-p.x:0;if(p&&p.pointer===e.pointerId&&p.axis==='x'&&Math.abs(dx)>70)commit(dx>0,p.signal);clear();}} onLostPointerCapture={clear} onPointerCancel={clear} style={{transform:`translateX(${drag}px) rotate(${drag/24}deg)`}}><header><span>PROFILE / {String(s.signal+1).padStart(3,'0')}</span><b>{candidate.quality.toUpperCase()} FIT</b></header><div className="f-signal-body"><span className="f-quote-mark">“</span><h2>{title}</h2><p>{SEGMENTS[s.channel]} · profile evidence, not a reroll</p><div className="f-signal-rule"/><dl><div><dt>NEED</dt><dd>{candidate.intent}</dd></div><div><dt>COMPATIBILITY</dt><dd>{candidate.quality==='qualified'?'High · Product job guaranteed':candidate.quality==='uncertain'?'Low · no Product job':'Poor · no Product job'}</dd></div><div><dt>MONTHLY STAKE</dt><dd>{money(P.monthlyPrices[s.channel])} ceiling</dd></div><div><dt>ACQUISITION CASH</dt><dd>{money(stake)} on pursue</dd></div></dl></div><footer>RIGHT = COMMIT THE PROFILE <b>↔</b></footer></article><span className={`f-swipe-label right ${drag>40?'lit':''}`}>PURSUE<br/>COMMIT CASH</span></div>
    <div className="f-gesture-caption"><button aria-label="Pass profile" onClick={()=>commit(false)}>← Pass</button><span>{s.market[s.channel].toLocaleString()} prospects in this month’s pool</span><button aria-label="Pursue profile" onClick={()=>commit(true)}>Pursue →</button></div>
    {resolution&&<div className={`f-demand-result ${resolution.outcome}`} role="status"><b>{resolution.outcome==='qualified'?`Product queue +${resolution.productJobs}`:resolution.outcome==='passed'?'Passed. Cash protected.':'No Product job.'}</b><span>{resolution.outcome==='qualified'?`${money(resolution.acquisitionCost)} acquisition cash committed · Product now has ${resolution.productQueueAfter} job${resolution.productQueueAfter===1?'':'s'}.`:resolution.outcome==='declined'?`${money(resolution.acquisitionCost)} was spent on a visible poor-fit profile. No queue change.`:'This profile left the desk with no cash spent.'}</span>{resolution.outcome==='qualified'&&<button onClick={()=>send({type:'focus',work:'product'})}>Open Product queue →</button>}</div>}</div>;
}
function skillEffect(s:Company,f:Work,a:Axis){const next=s.ranks[f][a]+1,definition=skillRank(f,a,next);
  if(definition)return definition.effect;
  if(a==='craft'&&f==='retention')return `${Math.max(1,P.bankHits-Math.floor(next/2))} hits per bank; care covers up to ${P.craft_batch_by_rank[next]} customers. A stronger swing, a bigger rescue.`;
  if(a==='scale'&&f==='operations')return `${P.units_by_scale_rank[next]} maintenance lanes. More coordination capacity and automated repair throughput.`;
  if(a==='craft')return `${P.craft_batch_by_rank[next]} outputs per successful attempt, limited by real inputs. ${f==='operations'?'Also increases coordination capacity.':f==='product'?'Each rank adds 2 points of shipped fit.':''}`;
  if(a==='scale')return `${P.units_by_scale_rank[next]} work lanes. Larger buffers and more automated throughput. Extra units cost $10/month each and add coordination load.`;
  if(a==='automate')return `${P.auto_speed_by_rank[next]}× manual speed per unit. ${money(P.auto_upkeep_cents_per_unit_month[next]*units(s,f))}/month compute. Actual jobs generate context rot.`;
  return `Output mean ${(100-next).toFixed(0)}%, wider swings. Shared market shocks cannot be diversified away. Risk persists across automated units.`;
}
function useOperationsLuck(active:boolean,scale:number,luck:number,automate:number,discount:boolean){
  return useMemo(()=>active?measureOperationsTickets(512,scale,luck,Math.max(1,automate),discount):null,[active,scale,luck,automate,discount]);
}
function Skills({s,send}:{s:Company;send:Send}){
  const [f,setF]=useState<Work>('demand');const [axis,setAxis]=useState<Axis>('automate');const rank=s.ranks[f][axis],next=rank+1,cost=skillCost(s,f,axis);const m=metrics(s);const preview=structuredClone(s);if(rank<4)preview.ranks[f][axis]++;const nextMetrics=metrics(preview);const definition=skillRank(f,axis,next);const finiteCap=f==='demand'?Math.max(0,Math.min(s.market[s.channel],units(preview,'product')*P.queue_slots_per_unit*batch(preview,'product')-count(s.leads))):f==='product'?Math.max(0,Math.min(count(s.leads),units(preview,'monetisation')*P.queue_slots_per_unit*batch(preview,'monetisation')-count(s.trials))):f==='monetisation'?count(s.trials):batch(preview,f);const luck=luckDistribution(next,batch(preview,f),finiteCap),operationsLuck=useOperationsLuck(f==='operations'&&axis==='luck',s.ranks.operations.scale,next,s.ranks.operations.automate,s.inventory.relics.includes('relic:reserved-instances'));
  return <div className="f-management"><span className="f-eyebrow">CAPABILITY / PERMANENT FOR THIS RUN</span><h1>Buy back your attention.</h1><p>Improve one part of the machine. Every new capability has a cash and coordination cost.</p><div className="f-skill-functions">{FUNCTIONS.map(x=><button key={x} aria-pressed={x===f} onClick={()=>setF(x)}>{NAMES[x]}<small>{AXES.reduce((n,a)=>n+s.ranks[x][a],0)} / 16 ranks</small></button>)}</div><div className="f-skill-tree"><div className="f-axis-list">{AXES.map(a=><button key={a} aria-pressed={axis===a} onClick={()=>setAxis(a)}><span>{a.toUpperCase()}</span><div>{[1,2,3,4].map(n=><i key={n} className={n<=s.ranks[f][a]?'owned':''}/>)}</div><small>{a==='craft'?'Better work':a==='scale'?'More work units':a==='automate'?'Hands become systems':'Choose more variance'}</small></button>)}</div><article className="f-skill-detail"><span>{NAMES[f].toUpperCase()} / {axis.toUpperCase()}</span><div className="f-rank-number">{rank===4?'04':`0${next}`}<small>/ 04</small></div><h2>{rank===4?'Fully installed.':definition?.name??(axis==='automate'?'A faster autonomous system.':axis==='craft'?'Make each attempt count.':axis==='scale'?'Give the work more room.':'Let the tails get wider.')}</h2><p>{rank===4?'This branch is fully deployed. Your next bottleneck lives elsewhere.':skillEffect(s,f,axis)}</p>{rank<4&&<><dl><div><dt>PREREQUISITE</dt><dd>{definition?.prerequisite??'Previous rank in this branch'}</dd></div><div><dt>CASH AFTER PURCHASE</dt><dd>{money(s.cash-cost)}</dd></div><div><dt>MONTHLY BILL AFTER INSTALL</dt><dd>{money(nextMetrics.cost)} <small>({money(nextMetrics.cost-m.cost)} change)</small></dd></div><div><dt>COMMITMENT</dt><dd>{definition?.recurringCommitment??'5 seconds to deploy'}</dd></div><div><dt>VISIBLE CHANGE</dt><dd>{definition?.visibleChange??'Capability instruments update'}</dd></div>{axis==='luck'&&operationsLuck?<><div><dt>WHOLE-TICKET NET</dt><dd>E {money(operationsLuck.automated.meanAfterPrice)} after price</dd></div><div><dt>AUTOMATED NET</dt><dd>E {money(operationsLuck.automated.meanAfterPriceAndUpkeep)} after allocated upkeep</dd></div><div><dt>TAIL RANGE</dt><dd>{money(operationsLuck.automated.minimum)} to {money(operationsLuck.automated.maximum)}</dd></div></>:axis==='luck'&&<><div><dt>RAW OUTPUT</dt><dd>E {luck.raw.mean.toFixed(2)} · variance {luck.raw.variance.toFixed(2)}</dd></div><div><dt>FINITE INPUT CAP</dt><dd>E {luck.capped.mean.toFixed(2)} / {finiteCap} · variance {luck.capped.variance.toFixed(2)}</dd></div></>}</dl><p className="f-risk-note">{definition?.downside??'Finite inputs and operating pressure still apply.'}</p><button className="f-primary" disabled={s.cash<cost} onClick={()=>send({type:'buy',work:f,axis,rank:next})}>Install {axis} {next} <b>{money(cost)}</b></button>{s.cash-cost<nextMetrics.cost&&<small className="f-risk-note">This purchase leaves less than one projected monthly bill in cash.</small>}</>}</article></div>{s.ranks[f].automate>0&&<button className="f-secondary" onClick={()=>send({type:'automation',work:f})}>{s.enabled[f]?'Switch off':'Restart'} {NAMES[f]} agents · {s.enabled[f]?'stop compute upkeep and new rot':'resume autonomous production'}</button>}{s.ranks[f].luck>0&&<button className="f-secondary f-risk-toggle" onClick={()=>send({type:'risk',work:f})} aria-pressed={s.risky[f]}>Luck exposure {s.risky[f]?'on':'off'} · {s.risky[f]?'disable risk':'enable explained seeded swings'}</button>}<div className="f-hud-progression"><span>INSTRUMENTS UNLOCK WITH INSTALLED CAPABILITY</span>{['Manual','Assisted','Swarm','Executive','Full capacity'].map((label,i)=><b key={label} className={tier(s)>=i?'active':''}>{label}</b>)}</div></div>;
}
function Finance({s,send}:{s:Company;send:Send}){
  const m=metrics(s),offers=capitalOffers(s),latest=s.reports.at(-1);
  const [confirm,setConfirm]=useState<CapitalOffer|{kind:'repay';loanId:number}|null>(null);
  const payment=s.debt?loanPayment(s.debt):null,payoff=s.debt?loanPayoff(s.debt,s.tick):null;
  const currentOffer=confirm?.kind==='debt'?offers.debt:confirm?.kind==='vc'?offers.vc:null;
  const stale=!!(confirm&&confirm.kind!=='repay'&&(!currentOffer?.available||confirm.key!==currentOffer.key));
  const last=s.actionResults.at(-1),rejected=last?.type==='ACTION_REJECTED'&&['borrow','raise','repay-debt'].includes(last.command);
  const accept=()=>{
    if(!confirm||stale)return;
    if(confirm.kind==='repay'){if(payoff&&s.debt?.id===confirm.loanId)send({type:'repay-debt',loanId:confirm.loanId,quote:payoff.key});}
    else send({type:confirm.kind==='debt'?'borrow':'raise',quote:confirm.key});
    setConfirm(null);
  };
  return <div className="f-management f-finance">
    <span className="f-eyebrow">TREASURY / TIME KEEPS RUNNING</span><h1>Cash is oxygen.</h1>
    <p>Stay liquid for the next bill. Zero cash alone is survivable; an unpaid obligation ends the run.</p>
    <div className="f-finance-metrics"><Metric label="LIQUID CASH" value={cash(s.cash)} major/><Metric label="MONTHLY REVENUE" value={cash(m.mrr)}/><Metric label="MONTHLY COST" value={cash(m.cost)}/><Metric label="OPERATING MARGIN" value={cash(m.mrr-m.cost)} warning={m.mrr<m.cost}/></div>
    <div className="f-cash-bridge"><div><span>EARNED, UNBILLED</span><b>{cash(m.unbilled)}</b></div><i>→</i><div><span>INVOICED, UNPAID</span><b>{cash(m.receivables)}</b></div><i>→</i><div><span>COLLECTED THIS Q</span><b>{cash(s.collected)}</b></div></div>
    <div className="f-obligations"><h2>The next commitments</h2>
      <div><span>Operating bill</span><b>~{cash(m.nextBill)} · {cash(s.expenseAccrued)} accrued</b><small>Due in {time(P.ticks_per_month-s.tick%P.ticks_per_month)}</small></div>
      {s.debt&&payment&&<><div><span>{payment.principal?'Loan principal + interest':'Loan interest'}</span><b>{cash(payment.total)}</b><small>Due in {time(s.debt.due-s.tick)} · {s.debt.aprBps/100}% APR{s.debt.mode==='amortising'?' · saved amortising terms':''}</small></div>
        <div><span>Principal remaining</span><b>{cash(s.debt.principal)}</b><small>{s.debt.mode==='interest-only'?'All due':'Fully repaid'} in {time(s.debt.maturity-s.tick)} · {s.debt.months} interest date{s.debt.months===1?'':'s'} left</small></div>
        <button className="f-secondary" disabled={!payoff||s.cash<payoff.total} onClick={()=>setConfirm({kind:'repay',loanId:s.debt!.id})}>Repay loan now · {cash(payoff!.total)}</button>
      </>}
      {s.vc&&<div><span>VC growth check</span><b>{cash(m.arr)} eligible ARR{s.vc.baselineLocked?` / ${cash(s.vc.rule==='quarter-growth'?s.vc.baseline:s.vc.target)} ${s.vc.rule==='quarter-growth'?'opening':'legacy target'}`:''}</b><small>{s.vc.baselineLocked?`${s.vc.rule==='quarter-growth'?'Finish above opening. Flat/down fails.':'Saved growth target applies.'} Review in ${time(s.vc.due-s.tick)}.`:`Grace period. Baseline locks in ${time(s.vc.startsAt-s.tick)}; first review in ${time(s.vc.due-s.tick)}.`}</small></div>}
    </div>
    {s.debt&&<details className="f-ledger"><summary>Loan repayment dates</summary>{loanSchedule(s.debt).map(p=><div key={p.at}><span>In {time(p.at-s.tick)}</span><b>{cash(p.total)}</b><small>{cash(p.interest)} interest{p.principal?` + ${cash(p.principal)} principal`:''}</small></div>)}</details>}
    <details className="f-ledger f-cash-forecast"><summary>Three-month cash forecast · low {cash(m.forecastMinimum)}</summary><p>Current contracts and committed bills. Collections are estimates; future sales are not assumed.</p>{forecast(s).events.slice(0,14).map((e,i)=><div key={i}><span>In {time(e.at-s.tick)} · {e.label}{e.estimated?' (estimate)':''}</span><b>{e.cents<0?'−':'+'}{cash(Math.abs(e.cents))}</b><small>Balance {cash(e.cash)}</small></div>)}</details>
    <div className="f-capital-choices"><article><span>OPTION 01 / DEBT</span><h2>Buy some runway.</h2><p>{cash(offers.debt.principal)} available. {offers.debt.aprBps/100}% APR; monthly interest. Principal due after {offers.debt.months} months, or repay early.</p><button className="f-secondary" disabled={!offers.debt.available} onClick={()=>setConfirm(offers.debt)}>{s.debt?'Loan outstanding':!offers.debt.available?`Needs ${cash(P.debt_min_mrr_cents)} eligible MRR`:'Review loan terms'}</button></article>
      <article><span>OPTION 02 / VENTURE CAPITAL</span><h2>Take the growth bet.</h2><p>{cash(offers.vc.cash)} cash for {P.vcOwnershipSoldBps/100}% dilution. Grow eligible ARR every full quarter. Flat or down ends the run.</p><button className="f-secondary" disabled={!offers.vc.available} onClick={()=>setConfirm(offers.vc)}>{s.vc?'VC mandate active':!offers.vc.available?`Needs ${cash(P.vc_min_arr_cents)} eligible ARR`:'Review equity terms'}</button></article></div>
    {rejected&&<p role="status">{last.reason==='unaffordable'?'Cash changed: the repayment is no longer affordable.':'These terms changed or are no longer available. Review the current offer.'}</p>}
    {confirm&&<div className="f-capital-confirm" role="region" aria-label="Confirm capital terms">
      <h3>{confirm.kind==='debt'?'Interest now. Principal later.':confirm.kind==='vc'?'A full quarter to prove growth.':'Close the loan.'}</h3>
      {confirm.kind==='debt'?<p>{cash(confirm.principal)} cash. {cash(confirm.interest)} first monthly interest in {time(P.ticks_per_month)} after acceptance. {confirm.aprBps/100}% APR; {confirm.months} months. All principal plus final interest becomes due at maturity. Early payoff includes accrued interest; no fee.</p>:confirm.kind==='vc'?<p>{cash(confirm.cash)} cash; founder ownership becomes {(confirm.ownership/100).toFixed(2)}%. {confirm.baselineLocked?`Opening eligible ARR: ${cash(confirm.baseline)}.`:`Opening ARR locks in ${time(confirm.startsAt-s.tick)}.`} First review at Q{confirm.due/QUARTER_TICKS} close, in {time(confirm.due-s.tick)}. Finish strictly above opening; flat/down fails. The partial funding quarter is exempt.</p>:payoff&&<p>{cash(payoff.principal)} principal + {cash(payoff.interest)} accrued interest = {cash(payoff.total)} now. Cash left: {cash(s.cash-payoff.total)}. Future loan bills stop. Accrued interest updates while time runs.</p>}
      {stale?<><p role="status">The offer changed while you reviewed it. Nothing was accepted.</p><button className="f-secondary" disabled={!currentOffer?.available} onClick={()=>currentOffer&&setConfirm(currentOffer)}>Refresh terms</button></>:<button className="f-primary" disabled={confirm.kind==='repay'&&(!payoff||s.cash<payoff.total||s.debt?.id!==confirm.loanId)} onClick={accept}>{confirm.kind==='repay'?`Repay ${cash(payoff?.total??0)}`:'Accept these terms'}</button>}
      <button className="f-secondary" onClick={()=>setConfirm(null)}>Keep current financing</button>
    </div>}
    {latest&&<div className="f-quarter-report"><span className="f-eyebrow">QUARTER {latest.quarter} / THE RECORD</span><h2>{money(latest.closing-latest.opening)} net ARR change.</h2><p>{money(latest.opening)} opening + {money(latest.newArr)} new + {money(latest.expansion)} expansion − {money(latest.churn)} churn = {money(latest.closing)} closing ARR.</p><p>{cash(latest.collected)} collected · {cash(latest.expenses)} expenses · {cash(latest.cash)} liquid at close.</p></div>}
    <details className="f-ledger"><summary>Why this company is worth {money(m.valuation)}</summary><p>{money(m.arr)} eligible ARR × {m.multiple.toFixed(2)} growth multiple × {m.stability.toFixed(3)} stability. Growth uses a trailing three-month window. Stability reflects operating strain, context rot, burn and forecast coverage. Financing creates cash, never ARR.</p><p>Lifetime earned {cash(s.lifetimeEarned)} = collected {cash(s.lifetimeCollected)} + receivables {cash(m.receivables)} + unbilled {cash(m.unbilled)} + bad debt {cash(s.badDebt)}.</p><p>Founder ownership {(s.ownership/100).toFixed(2)}% · contractual ARR {money(arr(s))}. Candidate game economy.</p></details>
  </div>;
}
function FinanceAlerts({s,send}:{s:Company;send:Send}){
  const payment=s.debt?loanPayment(s.debt):null;
  return <>{s.debt&&payment&&<button className={s.cash<payment.total?'f-alert':'f-obligation'} onClick={()=>send({type:'focus',work:'finance'})}><span>{payment.principal?'LOAN PRINCIPAL + INTEREST':'LOAN INTEREST'}</span><strong>{cash(payment.total)}</strong><small>In {time(s.debt.due-s.tick)} · principal {cash(s.debt.principal)} due in {time(s.debt.maturity-s.tick)}</small></button>}{s.vc&&<button className="f-alert" onClick={()=>send({type:'focus',work:'finance'})}>{s.vc.baselineLocked?`${s.vc.rule==='quarter-growth'?'Beat':'Reach'} ${cash(s.vc.rule==='quarter-growth'?s.vc.baseline:s.vc.target)} eligible ARR`:'VC grace: next full quarter counts'}<small style={{display:'block'}}>First/next review in {time(s.vc.due-s.tick)}{!s.vc.baselineLocked?` · baseline locks in ${time(s.vc.startsAt-s.tick)}`:''}</small></button>}</>;
}

function BuildContext({s,send}:{s:Company;send:Send}){
  const agents=FUNCTIONS.reduce((n,f)=>n+agentCount(s,f),0),charges=Object.entries(s.inventory.consumables).filter(([,count])=>count>0);
  const ranks=FUNCTIONS.reduce((n,f)=>n+AXES.reduce((sum,a)=>sum+s.ranks[f][a],0),0);
  return <section className="f-build-context"><span>YOUR RUN BUILD</span><dl><div><dt>Active lanes</dt><dd>{FUNCTIONS.reduce((n,f)=>n+agentStatus(s,f).activeCapacity,0)} / {FUNCTIONS.reduce((n,f)=>n+units(s,f),0)}</dd></div><div><dt>Skill purchases</dt><dd>{ranks} / 96</dd></div><div><dt>Compute</dt><dd>{agents} agents · {money(FUNCTIONS.reduce((n,f)=>n+computeCost(s,f),0))}/mo</dd></div></dl>
    {s.inventory.relics.map(id=>{const r=rewardById(id);return r&&<details className="f-relic" key={id}><summary>{r.name}<small>{BUILD_FAMILIES[r.family]}</small></summary><p>{REWARD_EFFECTS[r.effect].summary}</p><small>{r.downside} Lasts this run.</small></details>;})}
    {!s.inventory.relics.length&&<p>First quarter: choose what changes.</p>}
    {s.upgrades.length>0&&<small>Saved legacy effects: {s.upgrades.map(id=>UPGRADES.find(u=>u.id===id)?.name??id).join(' · ')}</small>}
    {s.inventory.active.map(b=><p className="f-active-consumable" key={b.id}>{rewardById(b.id)?.name} <b>{time(b.until-s.tick)}</b><small>active time left</small></p>)}
    {charges.length>0&&<details className="f-consumables"><summary>Consumables · {charges.reduce((n,[,count])=>n+count,0)} charges</summary>{charges.map(([id,count])=><Consumable key={id} id={id} count={count} s={s} send={send}/>)}</details>}
    <small>Founder history: {s.inheritedWins} prior wins · {money(s.inheritedWins*P.winCashBonus)} starting advantage. Run rewards reset next company.</small>
  </section>;
}
function Consumable({id,count,s,send}:{id:string;count:number;s:Company;send:Send}){
 const r=rewardById(id),[target,setTarget]=useState('');if(!r)return null;
 const choices=r.effect==='protect-threat'?s.accounts.filter(a=>a.active&&a.threat>s.tick).map(a=>({value:String(a.id),label:`${a.problem?.label??'Customer problem'} · ${a.count} customers`}))
  :r.effect==='reset-context'?FUNCTIONS.filter(f=>s.rot[f]>0).map(f=>({value:f,label:`${NAMES[f]} · ${Math.round(s.rot[f]*100)}% rot`})) :[];
 const selected=choices.some(c=>c.value===target)?target:choices[0]?.value;
 const account=r.effect==='protect-threat'?s.accounts.find(a=>String(a.id)===selected):undefined;
 const action:Extract<Command,{type:'consume'}>={type:'consume',id,...(account?{account:account.id,problem:account.problem?.id}:{}),...(r.effect==='reset-context'&&selected?{work:selected as Work}:{})};
 const use=consumableUse(s,action);
 return <div className="f-consumable"><b>{r.name} ×{count}</b><p>{REWARD_EFFECTS[r.effect].summary}{r.duration==='month'?' One active month.':''}</p>{choices.length>0&&<select aria-label={`${r.name} target`} value={selected} onChange={e=>setTarget(e.target.value)}>{choices.map(c=><option key={c.value} value={c.value}>{c.label}</option>)}</select>}<button className="f-secondary" disabled={!use.available} onClick={()=>send(action)}>{use.available?'Use one charge':use.reason}</button></div>;
}
function CompanyScope({s,intensity}:{s:Company;intensity:FeedbackIntensity}){
  const ref=useRef<HTMLCanvasElement>(null);
  useEffect(()=>{const canvas=ref.current;if(!canvas)return;const ctx=canvas.getContext('2d');if(!ctx)return;const dpr=Math.min(2,window.devicePixelRatio||1);canvas.width=220*dpr;canvas.height=145*dpr;ctx.scale(dpr,dpr);ctx.clearRect(0,0,220,145);const level=tier(s),color=level>=4?'#b8e2e6':level>=2?'#86c9cb':'#baa889';const points=FUNCTIONS.map((_,i)=>({x:110+62*Math.cos(-Math.PI/2+i*Math.PI/3),y:72+52*Math.sin(-Math.PI/2+i*Math.PI/3)}));ctx.strokeStyle=color+'55';ctx.lineWidth=1;for(let i=0;i<6;i++){const p=points[i],next=points[(i+1)%6];ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(next.x,next.y);ctx.stroke();if(level>=1){ctx.beginPath();ctx.moveTo(110,72);ctx.lineTo(p.x,p.y);ctx.stroke();}ctx.fillStyle=s.focus===FUNCTIONS[i]?color:'#262829';ctx.beginPath();ctx.arc(p.x,p.y,s.ranks[FUNCTIONS[i]].automate?6:3,0,Math.PI*2);ctx.fill();ctx.strokeStyle=color;ctx.stroke();if(intensity==='full'&&agentStatus(s,FUNCTIONS[i]).state==='running'&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches){const progress=s.credits[FUNCTIONS[i]];ctx.fillStyle=color;ctx.beginPath();ctx.arc(110+(p.x-110)*progress,72+(p.y-72)*progress,2,0,Math.PI*2);ctx.fill();}}
  ctx.fillStyle=color;ctx.font='22px monospace';ctx.textAlign='center';ctx.fillText('1',110,78);ctx.font='7px monospace';ctx.fillText('FOUNDER',110,91);
  },[s,intensity]);
  return <canvas ref={ref} className="f-company-scope" style={{width:'100%',height:145}} aria-label="Six connected work functions around one founder. Moving signals indicate autonomous work." role="img"/>;
}
function ProgressiveHUD({s}:{s:Company}){
  const stage=tier(s);if(stage<1)return <section className="f-garage-progress"><span>WORKBENCH / MANUAL EDITION</span><p>Your first 3 skill ranks unlock live capability instruments.</p><div>{[0,1,2].map(i=><i key={i} className={FUNCTIONS.reduce((n,f)=>n+AXES.reduce((v,a)=>v+s.ranks[f][a],0),0)>i?'installed':''}/>)}</div></section>;
  const max=Math.max(1,...s.history.map(h=>h.arr));const points=s.history.filter((_,i)=>i%6===0).map((h,i,list)=>`${i/Math.max(1,list.length-1)*180},${48-h.arr/max*44}`).join(' ');
  const craft=FUNCTIONS.reduce((n,f)=>n+s.ranks[f].craft,0),lanes=FUNCTIONS.reduce((n,f)=>n+units(s,f),0),agents=FUNCTIONS.reduce((n,f)=>n+agentCount(s,f),0);
  return <section className="f-earned-hud"><div className="f-capability-instruments"><article><small>CRAFT</small><b>{craft}</b><span>installed ranks</span></article><article><small>SCALE</small><b>{lanes}</b><span>work lanes</span></article><article><small>AUTOMATE</small><b>{agents}</b><span>agent systems</span></article></div><span>{stage<2?'AGENT TELEMETRY':stage<3?'SWARM TELEMETRY':'EXECUTIVE INSTRUMENTS'}</span>{FUNCTIONS.filter(f=>s.ranks[f].automate>0).map(f=>{const agent=agentStatus(s,f);return <div key={f} title={`${agent.installed} installed agents · ${agent.activeCapacity}/${agent.lanes} active lanes · ${money(agent.compute)}/mo · ${Math.round(agent.speed*100)}% pace`}><span>{NAMES[f]}<small style={{display:'block'}}>{agent.label}{agent.state==='running'?` · ${Math.round(agent.speed*100)}% pace`:''}</small></span><div role="progressbar" aria-label={`${NAMES[f]} agent step`} aria-valuemin={0} aria-valuemax={100} aria-valuenow={Math.round(agent.progress*100)}><i style={{width:`${agent.progress*100}%`}}/></div><b>{s.completed[f]}</b></div>})}{stage>=2&&<p>Completed output. Open a room to take control; leave to resume agents.</p>}{stage>=3&&<><span>ELIGIBLE ARR / TRAILING QUARTER</span><svg viewBox="0 0 180 55" role="img" aria-label="Trailing quarter eligible ARR chart"><polyline points={points} fill="none" stroke="currentColor" strokeWidth="1.5"/></svg><p>{money(metrics(s).arr)} ARR · {Math.round(metrics(s).stability*100)}% stability</p></>}</section>;
}
